```python
import sys

class RoadSystem:
    def __init__(self, n):
        self.n = n
        self.roads = {}
        for _ in range(n):
            u, v, l = map(int, input().split())
            self.roads[(u, v), (v, u)] = l
            self.roads[(u, v)] = l  # Create symmetric edges for convenience

    def find_shortest(self, u, v):
        def is_invariant(x, y, distance_check_func):
            v_x, w_y, _ = x
            w, r_y, _ = y
            if distance_check_func(v_x, w_y) and distance_check_func(w, r_y) and distance_check_func(v_x, r_y):
                return True
            return False

        def part_one(x, distance_check_func):
            prev_u = x[0][0]
            distinct_s = set([x[0]] + list(map(lambda y: (y[0], distance_check_func(*y)), x[0])))
            for y in x:
                if distance_check_func(*y) == 0:
                    return []
                for i in range(len(y)):
                    for j in range(len(y[i])):
                        if is_invariant(selected := [y[i]], distinct_s, distance_check_func):
                            return [prev_u] + selected + [y[i][j]]
                prev_u = y
            return [prev_u]

        paths = []
        for u in range(1, self.n + 1):
            for v in range(1, self.n + 1):
                edges = set([self.roads[(u, v)], self.roads[(v, u)]])
                if edges not in paths and len(edges) == 2:
                    if all(is_invariant(edge) for edge in edges):
                        paths.append(edges)
                    elif all(is_invariant({v}, {w}) for v in [u] for w in {v} if (v, w) not in paths):
                        paths.append({v, w} if len({v, w} & edges) > 2 else [w])
                    elif all(is_invariant({u}, {w}) for w in [v] for w in {w} if (w, u) not in paths):
                        paths.append({w, u} if len({w, u} & edges) > 2 else [u])

        return paths

    def find_inconvenience_min(self):
        paths = self.find_shortest(1, self.roads)

        min_incon = float('inf')
        for path in paths:
            for u, v in path:
                inco = -self.roads[(u, v)]
                if inco < min_incon:
                    min_incon = inco
        return min_incon

def main(input_file):
    with open(input_file, 'r') as f:
        n = int(f.readline())
        road_system = RoadSystem(n)
        print(road_system.find_inconvenience_min())

if __name__ == "__main__":
    main(sys.argv[1])
