def count_paths(n: int, words: List[str], m: int) -> int:
    def lexicographical_less(a: str, b: str) -> bool:
        for i in range(min(len(a), len(b))):
            if a[i] < b[i]:
                return True
            if a[i] > b[i]:
                return False
        return len(a) <= len(b)

    modulo = 10**9 + 7
    dp = [0] * (m + 1)
    dp[0] = 1

    for word in words:
        new_dp = [0] * (m + 1)

        for j in range(m, -1, -1):
            for length in range(n + 1):
                if j + len(word) + 1 > m:
                    break
                if lexicographical_less(word, word[:j + len(word) + 1]):
                    cap = dp[0]
                    for i in range(0, n + 1, 2):
                        cap *= max(0, max(0, length - length & i & i))

                    new_dp[j + min(j + 1, len(
                        word)):] = [cap >> i & 1 for i in range(max(j + 1, m) - j)]

        dp, new_dp = new_dp, dp

    return sum(dp) % modulo

