from functools import lru_cache

def calculate_standings(n, intervals):
    @lru_cache(None)
    def dp(state, current):
        if current + 1 > n:
            return 0
        if all(current + i >= n for i in state):  # All scores higher than n
            return 1.0
        if current in state:
            return 1.0 - dp(tuple(state), current + 1)
        if len(state) == 1:
            return 1.0 if current <= state[0] else 0.0
        if current == state[0]:
            return 1.0 - dp((state[1] + 1,) + tuple(state[2:]), current + 1)
        else:
            return 1.0 - dp(tuple(sorted(state))[:-1], current + 1)

    # Broadcasting the input to n x n matrix
    score_matrix = [[0] * n for _ in range(n)]

    for i, (start, end) in enumerate(intervals):
        score_matrix[start][i] = score_matrix[start][i + 1] = 1.0 - dp((start,) + tuple(end,), 0)
        score_matrix[i + 1][i] = score_matrix[i + 1][i + 1] = 1.0 - dp(tuple(end,), i + 1)

    for i in range(n):
        score_matrix[0][i] = dp(tuple(current + 1, current), 0)
    for j in range(n):
        score_matrix[j][0] = dp(tuple(j, j + 1), 0)

    return score_matrix

