def max_score_permutations(n, m):
    if n == 1 or n == 2 or m == 0:
        return [1, 2], [1, 2]
    pairs = [(l, r) for l, r in pairwise(range(1, n + 1))]
    all_pairs = list(permutations(range(1, n + 1), 2))[:m]
    neg_count = pos_count = 0
    permutation = list(permutations(range(1, n + 1)))
    result = [[permutation[i][j] for i in range(n)] for j in range(n)]

    for pair in all_pairs:
        if sum(permutation[pair[0] - 1][k] - permutation[pair[1] - 1][k] for k in range(n)) < 0:
            neg_count += 1
            result[pair[0] - 1][pair[1] - 1] = permutation[pair[0] - 1][pair[1] - 1]
            result[pair[1] - 1][pair[0] - 1] = permutation[pair[1] - 1][pair[0] - 1]
