            result[pair[0] - 1][pair[1] - 1] = permutation[pair[1] - 1][pair[0] - 1]
            result[pair[1] - 1][pair[0] - 1] = permutation[pair[0] - 1][pair[1] - 1]

    scores = [0] * m
    for i, r in enumerate(result):
        for p, q in pairwise(r):
            scores[i] += (p - q) * (q < p)

    max_score = max(scores)
    for i, r in enumerate(result):
        if scores[i] == max_score:
            return result

