from math import gcd
from functools import reduce

def lcm(num_one, num_two):
    return (num_two * num_one) // gcd(num_one, num_two)

def find_lex_smallest_permutation(A: List[int]) -> List[int]:
    mod_arr = []

    # Find modulo operation results
    for i in range(1, len(A) + 1):
        if A[-i] > A[-1]:
            mod_arr.append(i)

    # Perform Euler's theorem for modulo operation
    g = find_gcd(len(A), gcd(*mod_arr))
    c = gcd(*mod_arr)

    mod_arr.append(g + 1)

    c = reduce(lcm, mod_arr)

    for i in range(len(A)):
        A[i] = (A[i] - 1) % c + 1

    return A

def find_gcd(nums):
    return reduce(gcd, nums)
