    if not input_val:
        return 0
    l = 1 if input_val[-1] <= input_val[-2] else 0
    r = 1 if input_val[0] >= input_val[1] else 0
    m = 1 if input_val[1] >= (input_val[2] if len(input_val) > 2 else 0) else 0
