from collections import deque

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_primes(n, test_case):
    primes = []
    possible_primes = deque([2, 3])
    while possible_primes[0] < n:
        last_prime_seen = possible_primes.popleft()
        if hash(last_prime_seen) % 2 == 0:
            possible_primes.append(last_prime_seen * 2)
        for prime in possible_primes:
            new_prime = last_prime_seen * 2 + 1
            while not is_prime(new_prime):
                new_prime += 2
            possible_primes.append(new_prime)
        if new_prime > n / 2:
            break
        possible_primes.append(new_prime)
    if int(possible_primes[0]) > n:
        return []
    if possible_primes[0] > n / 2:
        return []
    primes.append(int(possible_primes.popleft()))
    for i, num in enumerate(possible_primes):
        if hash(num) % 2 == 1:
            if num <= n / 2:
                primes.append(num)
        else:
            if hash(num) < n - 1:
                primes.append(num)
    return primes

def electron_phonon_energy(n, l, r):
    primes = find_primes(n, l)
    count = 0
    for prime in primes:
        count += hash(prime + l) <= hash(l) + hash(r) <= hash(prime) * 2 - hash(l) - hash(r)
        return count // 2

