MOD = 1000000007

def count_triangle_areas(w, h):
    if w < 0 or h < 0:
        raise ValueError("Dimensions must be non-negative integers.")
    if w <= 1 or h <= 1:
        return h * (w - 1) * 4

    triangle_counts = [0] * (w + 1)
    triangle_counts[1] = 1
    for height in range(1, h + 1):
        total_triangles = 0
        for width in range(1, w + 1):
            total_triangles += (width - 1) * 2 * height + 1
            total_triangles %= MOD
        for width in range(2, w + 1):
            for previous_width in range(1, width - 1):
                triangles_through_previous = 3
                if previous_width in triangle_counts:
                    triangles_through_previous *= triangle_counts[previous_width]
                else:
                    triangles_through_previous = 4
                triangles_through_previous %= MOD
                total_triangles -= (width - previous_width - 1) * triangles_through_previous
        triangle_counts[1] += (h - 1) * total_triangles
        triangle_counts[1] %= MOD

    total_area = 0
    for i in range(1, w + 1):
        total_area += triangle_counts[i]
        total_area %= MOD

    return total_area


